import {maskBounds} from './removal-math.js';
export function rankColorCandidates(result,points,mode='garment',faces=[],excludeReflection=true){let best=-1,rank=-Infinity;for(let i=0;i<result.masks.length;i++){const m=result.masks[i],w=result.width,h=result.height,b=maskBounds(m,w,h,.5);if(!b)continue;const area=b.count/(w*h);if(area<.003||area>.75)continue;let value=result.scores[i]||0;for(const p of points){const j=Math.min(h-1,Math.floor(p.y*h))*w+Math.min(w-1,Math.floor(p.x*w));if(p.label?m[j]<.4:m[j]>.5)value-=1;}if(mode==='garment'){let faceOverlap=0;for(const f of faces){let n=0,sum=0;for(let y=Math.max(0,Math.floor((f.y+f.height*.15)*h));y<Math.min(h,(f.y+f.height*.85)*h);y+=3)for(let x=Math.max(0,Math.floor((f.x+f.width*.2)*w));x<Math.min(w,(f.x+f.width*.8)*w);x+=3){sum+=m[y*w+x]>.5?1:0;n++;}faceOverlap=Math.max(faceOverlap,sum/Math.max(1,n));}value+=Math.min(.01,area*.015)-faceOverlap*1.2;if(area>.65)value-=.3;}else{value+=Math.sqrt(area)*.8;if(excludeReflection&&b.bottom>=h-1)value-=.65;}if(value>rank){rank=value;best=i;}}if(best<0)throw Error('Vùng chọn chưa rõ. Bấm giữa vùng hoặc dùng cọ.');return {...result,best,values:result.masks[best]};}
export async function selectColor(preview,client,{mode='garment',points,imageKey='',faces=null,excludeReflection=true,progress=()=>{},alive=()=>true}={}){const guard=()=>{if(!alive())throw new DOMException('Cancelled','AbortError');};let detected=faces;if(mode==='garment'&&!detected){try{detected=(await client.run(preview,{mode:'faces',imageKey},progress)).faces||[];}catch(e){if(e.name==='AbortError')throw e;detected=[];}guard();}let result=await client.run(preview,{mode:'point',points,imageKey},progress);guard();result=rankColorCandidates(result,points,mode,detected||[],excludeReflection);if(mode==='beverage'&&excludeReflection&&points.length===1&&points[0].y<.8){const b=maskBounds(result.values,result.width,result.height,.5);if(b?.bottom>=result.height-1){const seeds=[...points,{x:points[0].x,y:.94,label:0}],retry=await client.run(preview,{mode:'point',points:seeds,imageKey},progress);guard();result=rankColorCandidates(retry,seeds,mode,[],true);}}return {...result,faces:detected||[]};}
